mkdir -p scratch/qilin && cat > scratch/qilin/run.ts <<'EOF'
import * as THREE from "three";
import build, { meta } from "../../samples/qilin";
const root = build();
const box = new THREE.Box3().setFromObject(root, true);
let meshes = 0, tris = 0; const bones = new Set<string>();
root.traverse((o: any) => { if (o.isMesh) { meshes++; const g = o.geometry; tris += (g.index ? g.index.count : g.attributes.position.count) / 3; } if (o.isBone || o.type==="Group" || o.type==="Object3D") bones.add(o.name); });
console.log(meta.name, "meshes", meshes, "tris", tris, "box", box.min.toArray().map(n=>n.toFixed(3)), box.max.toArray().map(n=>n.toFixed(3)));
console.log("joints approx", (root.userData.rig?.joints?.length), Object.keys(root.userData));
EOF
npx tsx scratch/qilin/run.ts 2>&1 | tail -30
